using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;
namespace Ara {public static class NotionHubTests {
 static void Assert(bool value,string why){if(!value)throw new Exception(why);}
 static NotionHub Fake(string dir){var hub=new NotionHub(Path.Combine(dir,"state.json"));var data=JsonMap.Obj("access_token","only_a_fake_access_token_for_tests","refresh_token","only_a_fake_refresh_token","client_id","fake-client","expires_at",long.MaxValue);typeof(NotionHub).GetField("vault",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(hub,data);return hub;}
 public static void Run(Action<string,Action> check,string dir){
  check("notion hub: only setup and read tools allowed, no record writes or arbitrary tools",()=>{Assert(NotionHub.AllowedTool("notion-search")&&NotionHub.AllowedTool("notion-create-database")&&NotionHub.AllowedTool("notion-create-view"),"setup");Assert(!NotionHub.AllowedTool("notion-update-page")&&NotionHub.AllowedTool("notion-create-pages")&&!NotionHub.AllowedTool("notion-spawn-session"),"blocked");});
  check("notion hub: SSE selects matching response and rejects another ID",()=>{var value=NotionHub.ParseRpc("event: message\ndata: {\"jsonrpc\":\"2.0\",\"id\":8,\"result\":{}}\n\ndata: {\"id\":9,\"result\":{\"ok\":true}}\n",9);Assert(JsonMap.Str(JsonMap.Child(value,"result"),"ok")=="True","matching");bool rejected=false;try{NotionHub.ParseRpc("{\"id\":8,\"result\":{}}",9);}catch(InvalidDataException){rejected=true;}Assert(rejected,"wrong id");});
  check("notion hub: status never exposes access or refresh credential",()=>{var hub=Fake(Path.Combine(dir,"hub-status"));string text=JsonMap.Write(hub.Request(JsonMap.Obj("op","status")));Assert(!text.Contains("fake_access")&&!text.Contains("refresh_token")&&text.Contains("connected"),"redacted");});
  check("notion hub: setup destination and credential survive DPAPI reload without plaintext",()=>{string path=Path.Combine(dir,"hub-vault");var hub=Fake(path);string id=Guid.NewGuid().ToString();hub.Request(JsonMap.Obj("op","target","target",JsonMap.Obj("id",id,"kind","data_source","title","한글 저장 위치")));byte[] bytes=File.ReadAllBytes(Path.Combine(path,"notion-oauth.bin"));Assert(!Encoding.UTF8.GetString(bytes).Contains("fake_access"),"encrypted");var restored=new NotionHub(Path.Combine(path,"state.json"));var status=JsonMap.Map(restored.Request(JsonMap.Obj("op","status")));Assert(JsonMap.Str(status,"connected")=="True"&&JsonMap.Str(JsonMap.Child(status,"target"),"id")==id,"reload");});
  check("notion hub: expired credential rotates refresh token before tool use",()=>{string path=Path.Combine(dir,"hub-refresh");var hub=Fake(path);var vault=(Dictionary<string,object>)typeof(NotionHub).GetField("vault",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(hub);vault["expires_at"]=1;bool rotated=false;hub.Transport=(method,url,body,token)=>{if(url=="/token"){rotated=true;Assert(body.Contains("refresh_token")&&!body.Contains("fake_access"),"refresh request");return JsonMap.Obj("access_token","new_fake_access_token","refresh_token","rotated_fake_refresh_token","expires_in",3600);}Assert(token=="new_fake_access_token","fresh access");var input=JsonMap.Read(body);return JsonMap.Obj("id",input.ContainsKey("id")?input["id"]:0,"result",JsonMap.Obj("tools",new object[0]));};hub.Request(JsonMap.Obj("op","tools"));Assert(rotated&&JsonMap.Str(vault,"refresh_token")=="rotated_fake_refresh_token","rotation saved");});
  check("notion pages: private and selected-parent empty pages accept only one title",()=>{NotionHub.ValidatePageCreate(JsonMap.Obj("creation_mode","draft","allow_async",false,"pages",new[]{JsonMap.Obj("properties",JsonMap.Obj("title","새 보관함"))}));NotionHub.ValidatePageCreate(JsonMap.Obj("parent",JsonMap.Obj("page_id",Guid.NewGuid().ToString()),"pages",new[]{JsonMap.Obj("properties",JsonMap.Obj("title","하위"))}));});
  check("notion pages: bulk, body and database-row creation remain blocked",()=>{int rejected=0;foreach(var input in new[]{JsonMap.Obj("creation_mode","draft","pages",new object[0]),JsonMap.Obj("creation_mode","draft","pages",new[]{JsonMap.Obj("properties",JsonMap.Obj("title","x"),"content","upload")}),JsonMap.Obj("parent",JsonMap.Obj("data_source_id",Guid.NewGuid().ToString()),"pages",new[]{JsonMap.Obj("properties",JsonMap.Obj("title","x"))})})try{NotionHub.ValidatePageCreate(input);}catch(InvalidDataException){rejected++;}Assert(rejected==3,"bounded creates");});
  check("notion hub: result decoder handles structured and text JSON plus errors",()=>{var data=NotionConnectWindow.Decode(JsonMap.Obj("content",new[]{JsonMap.Obj("type","text","text","{\"title\":\"한글\"}")}));Assert(JsonMap.Str(data,"title")=="한글","JSON");bool failed=false;try{NotionConnectWindow.Decode(JsonMap.Obj("isError",true));}catch(InvalidOperationException){failed=true;}Assert(failed,"error");});
  check("notion hub: created database destination uses real collection ID",()=>{string db=Guid.NewGuid().ToString(),source=Guid.NewGuid().ToString();var target=NotionConnectWindow.Destination(JsonMap.Obj("text","<database url=\"https://www.notion.so/"+db+"\"><data-source url=\"collection://"+source+"\">날짜</data-source></database>"));Assert(JsonMap.Str(target,"id")==source&&JsonMap.Str(target,"kind")=="data_source","source");});
  check("notion hub: daily schema distinguishes waking date, weighted scores and total",()=>{string schema=NotionConnectWindow.Schema;Assert(schema.Contains("기상한 날짜")&&schema.Contains("\"집중도\" NUMBER")&&schema.Contains("\"만족도\" NUMBER")&&schema.Contains("\"집중 총점\" NUMBER"),"typed properties");});
  check("notion hub: disconnect removes only local Notion credentials and destination",()=>{string path=Path.Combine(dir,"hub-disconnect");var hub=Fake(path);hub.Request(JsonMap.Obj("op","disconnect"));var restored=new NotionHub(Path.Combine(path,"state.json"));Assert(JsonMap.Str(JsonMap.Map(restored.Request(JsonMap.Obj("op","status"))),"connected")=="False","forgotten");});
 }
}}
